以 List 實踐 Queue程式碼#include &lt;iostream&gt;#include &lt;vector&gt;using namespace std;class QueueList&#123; private: int front, back; vector&lt;int&gt; queue; public: QueueList():front(NULL), back(NULL), queue(NULL)&#123;&#125; void Push(int x); void Pop(); int getFront(); int getBack(); int getSize(); bool IsEmpty();&#125;;void QueueList::Push(int x) &#123; queue.push_back(x); return;&#125;void QueueList::Pop()&#123; if(queue.empty())&#123; cout &lt;&lt; &quot;empty queue&quot; &lt;&lt; endl; return; &#125; else&#123; queue.erase(queue.begin()); return; &#125;&#125;int QueueList::getFront()&#123; if(queue.empty())&#123; cout &lt;&lt; &quot;empty queue&quot; &lt;&lt; endl; return -1; &#125; else&#123; vector&lt;int&gt;::iterator it=queue.begin(); return *it; &#125;&#125;int QueueList::getBack()&#123; if(queue.empty())&#123; cout &lt;&lt; &quot;empty queue&quot; &lt;&lt; endl; return -1; &#125; else&#123; vector&lt;int&gt;::iterator it=queue.end()-1; return *it; &#125;&#125;int QueueList::getSize()&#123; return queue.size();&#125;bool QueueList::IsEmpty()&#123; if(queue.empty())&#123; return true; &#125; else&#123; return false; &#125;&#125;int main()&#123; QueueList q; q.Push(25); cout &lt;&lt; &quot;After Pushing 25: &quot; &lt;&lt; &quot;front:&quot; &lt;&lt; q.getFront() &lt;&lt; &quot; back:&quot; &lt;&lt; q.getBack() &lt;&lt; endl; q.Push(50); cout &lt;&lt; &quot;After Pushing 50: &quot; &lt;&lt; &quot;front:&quot; &lt;&lt; q.getFront() &lt;&lt; &quot; back:&quot; &lt;&lt; q.getBack() &lt;&lt; endl; q.Push(77); cout &lt;&lt; &quot;After Pushing 77: &quot; &lt;&lt; &quot;front:&quot; &lt;&lt; q.getFront() &lt;&lt; &quot; back:&quot; &lt;&lt; q.getBack() &lt;&lt; endl; q.Pop(); cout &lt;&lt; &quot;After Poping the front element: &quot; &lt;&lt; &quot;front:&quot; &lt;&lt; q.getFront() &lt;&lt; &quot; back:&quot; &lt;&lt; q.getBack() &lt;&lt; endl; q.Pop(); cout &lt;&lt; &quot;After Poping the front element: &quot; &lt;&lt; &quot;front:&quot; &lt;&lt; q.getFront() &lt;&lt; &quot; back:&quot; &lt;&lt; q.getBack() &lt;&lt; endl; q.Pop(); cout &lt;&lt; &quot;After Poping the front element: &quot; &lt;&lt; &quot;front:&quot; &lt;&lt; q.getFront() &lt;&lt; &quot; back:&quot; &lt;&lt; q.getBack() &lt;&lt; endl; q.Pop(); cout &lt;&lt; &quot;After Poping the front element: &quot; &lt;&lt; &quot;front:&quot; &lt;&lt; q.getFront() &lt;&lt; &quot; back:&quot; &lt;&lt; q.getBack() &lt;&lt; endl; return 0; &#125;
